<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Mano de obra | CampoSur</title><link rel="stylesheet" href="/assets/css/app.css"></head><body class="admin-page"><main class="admin-shell"><?php require dirname(__DIR__) . '/Views/partials/module-navigation.php'; ?><header class="admin-header"><div><p class="eyebrow">Trabajadores</p><h1>Mano de obra</h1><p class="setup-copy">Registra a tus trabajadores y las labores que realizan.</p></div><a class="secondary-link" href="/">Volver al dashboard</a></header><?php if ($error): ?><div class="setup-error"><?= htmlspecialchars($error) ?></div><?php endif; ?><?php if ($success): ?><div class="setup-success"><?= htmlspecialchars($success) ?></div><?php endif; ?><section class="admin-columns"><article class="admin-panel"><header class="panel-header"><h2>Nuevo trabajador</h2><p>Personas permanentes, temporales o contratistas</p></header><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="create_worker"><label>Nombre completo<input name="full_name" required></label><label>RUT<input name="tax_id"></label><label>Tipo<select name="worker_type"><option value="PERMANENTE">Permanente</option><option value="TEMPORAL">Temporal</option><option value="CONTRATISTA">Contratista</option></select></label><label>Tarifa base<input type="number" name="default_rate" min="0" step="0.01"></label><button class="primary-button" type="submit">Crear trabajador</button></form></article><article class="admin-panel"><header class="panel-header"><h2>Registrar labor</h2><p>El total se calcula con cantidad por tarifa</p></header><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="create_labor"><label>Trabajador<select name="worker_id" required><?php foreach ($workers as $worker): ?><option value="<?= (int) $worker['id'] ?>"><?= htmlspecialchars($worker['full_name']) ?></option><?php endforeach; ?></select></label><label>Temporada<select name="season_id" required><?php foreach ($seasons as $season): ?><option value="<?= (int) $season['id'] ?>"><?= htmlspecialchars($season['name']) ?></option><?php endforeach; ?></select></label><label>Fundo<select name="farm_id"><option value="">Sin fundo</option><?php foreach ($farms as $farm): ?><option value="<?= (int) $farm['id'] ?>"><?= htmlspecialchars($farm['name']) ?></option><?php endforeach; ?></select></label><label>Cuartel<select name="block_id"><option value="">Sin cuartel</option><?php foreach ($blocks as $block): ?><option value="<?= (int) $block['id'] ?>"><?= htmlspecialchars($block['code'] . ' · ' . $block['name']) ?></option><?php endforeach; ?></select></label><label>Fecha<input type="date" name="labor_date" required value="<?= date('Y-m-d') ?>"></label><label>Labor<input name="labor_type" required placeholder="Poda, raleo, cosecha"></label><label>Cantidad<input type="number" name="quantity" min="0.01" step="0.01" required></label><label>Tarifa unitaria<input type="number" name="unit_rate" min="0" step="0.01" required></label><button class="primary-button" type="submit">Registrar labor</button></form></article></section><section class="admin-panel"><header class="panel-header"><h2>Trabajadores registrados</h2><p><?= count($workers) ?> personas</p></header><div class="table-scroll"><table class="admin-table"><thead><tr><th>Trabajador</th><th>Tipo</th><th>Tarifa base</th><th>Estado</th></tr></thead><tbody><?php foreach ($workers as $worker): ?><tr><td><b><?= htmlspecialchars($worker['full_name']) ?></b><small><?= htmlspecialchars($worker['tax_id'] ?: 'Sin RUT') ?></small></td><td><?= htmlspecialchars($worker['worker_type']) ?></td><td>$<?= number_format((float) $worker['default_rate'], 0, ',', '.') ?></td><td><span class="status-pill status-active">Activo</span></td></tr><?php endforeach; ?></tbody></table></div></section><section class="admin-panel labor-entries"><header class="panel-header"><h2>Últimas labores</h2><p>Historial operativo</p></header><div class="table-scroll"><table class="admin-table"><thead><tr><th>Fecha</th><th>Trabajador</th><th>Labor</th><th>Ubicación</th><th>Total</th></tr></thead><tbody><?php foreach ($entries as $entry): ?><tr><td><?= htmlspecialchars($entry['labor_date']) ?></td><td><?= htmlspecialchars($entry['full_name']) ?></td><td><?= htmlspecialchars($entry['labor_type']) ?></td><td><?= htmlspecialchars($entry['farm_name'] ?: 'Sin fundo') ?></td><td><b>$<?= number_format((float) $entry['total_amount'], 0, ',', '.') ?></b></td></tr><?php endforeach; ?></tbody></table></div></section></main></body></html>
